changeSet.sql:
SET time_zone = '+00:00';

-- The "never banned" tempban is DefaultDates.getTempban(), which Client and Character compare as a JVM
-- (GMT) wall clock, 2005-05-11 00:00. Rows written through the table default or an old session hold
-- 2005-05-11 00:00 in the host zone instead. No real temp ban ends in 2005.
UPDATE accounts SET tempban = '2005-05-11 00:00:00'
WHERE tempban BETWEEN '2005-05-10 00:00:00' AND '2005-05-12 00:00:00' AND tempban <> '2005-05-11 00:00:00';

-- A TIMESTAMP column's constant default is fixed in the zone of the session that set it.
ALTER TABLE accounts ALTER COLUMN tempban SET DEFAULT '2005-05-11 00:00:00';

-- A GMT wall clock sent through a New York session stored its instant 4-5 h late, and a load and save
-- across the two kinds of connection added another shift. Such a time can be in the future, which a
-- last login, logout or exp gain can't be. Older shifted rows can't be told apart and are left.
UPDATE accounts SET lastlogin = NOW() WHERE lastlogin > NOW();
UPDATE characters SET lastLogoutTime = NOW() WHERE lastLogoutTime > NOW();
UPDATE characters SET lastExpGainTime = NOW() WHERE lastExpGainTime > NOW();
